        for line in f:
            parts = line.rstrip('\n').split('\t')
            if len(parts) >= 2:
                candidate = parts[1].strip()
                if candidate.startswith('ORD-') and len(candidate) == 8:
                    last_id = candidate

    if last_id is None:
        next_suffix = '0000'
    else:
        suffix = last_id[4:]  # e.g. '243G'
        n = base36_decode(suffix)
        n = (n + 1) % (36 ** 4)  # wrap around if overflow
        next_suffix = base36_encode(n)

    print(f'ORD-{next_suffix}')


