import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    if n == 0:
        return "0"
    digits = []
    while n > 0:
        digits.append(BASE36[n % 36])
        n //= 36
    return "".join(reversed(digits))


def from_base36(s: str) -> int:
    n = 0
    for ch in s:
        n = n * 36 + BASE36.index(ch.upper())
    return n


def next_id(current: str) -> str:
    suffix = current[4:]  # strip "ORD-"
    num = from_base36(suffix)
    num += 1
    next_suffix = to_base36(num).upper().rjust(4, "0")
    return f"ORD-{next_suffix}"


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last = lines[-1]
    print(next_id(last))


if __name__ == "__main__":
    main()
