#!/usr/bin/env python3
"""Read events.jsonl, remove duplicates by event_id, write deduped.jsonl."""

import json


def main() -> None:
    seen: set[str] = set()
    out_lines: list[str] = []

    with open("events.jsonl") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            eid = event["event_id"]
            if eid not in seen:
                seen.add(eid)
                out_lines.append(line)

    with open("deduped.jsonl", "w") as f:
        for line in out_lines:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

