"""Generate manifest.json with SHA-256 digests of all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}

    for fpath in sorted(RELEASE_DIR.rglob("*")):
        if not fpath.is_file():
            continue
        rel = fpath.relative_to(RELEASE_DIR)
        manifest[str(rel)] = sha256_digest(fpath)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")
    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

