#!/usr/bin/env python3
"""Write manifest.json: a JSON object mapping each file under release/ to its SHA-256 hex digest."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def main() -> None:
    manifest: dict[str, str] = {}

    # Walk all files recursively under release/
    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        rel_path = path.relative_to(RELEASE_DIR.parent)
        digest = hashlib.sha256(path.read_bytes()).hexdigest()
        manifest[str(rel_path)] = digest

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n")
    print(f"Wrote {MANIFEST_PATH.name} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

