#!/usr/bin/env python3
"""Print the file names under reports/, one per line, in report order."""

import os
import re


def report_sort_key(name: str) -> tuple:
    """Return a sort key that orders report-N.txt by N numerically."""
    m = re.search(r"report-(\d+)", name)
    if m:
        return (0, int(m.group(1)))
    return (1, name)


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    files = os.listdir(reports_dir)
    files.sort(key=report_sort_key)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

