#!/usr/bin/env python3
"""List report files under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(path: str) -> int:
    """Extract numeric portion from a filename like report-3.txt."""
    m = re.search(r"(\d+)", path)
    return int(m.group(1)) if m else 0


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    # Keep only files matching report-N.txt
    report_files = [
        e for e in entries
        if re.match(r"report-\d+\.\w+$", e) and os.path.isfile(os.path.join(REPORTS_DIR, e))
    ]

    report_files.sort(key=report_sort_key)

    for f in report_files:
        print(f)


if __name__ == "__main__":
    main()

