"""Print the file names under reports/, one per line, in report order.

Reports are named report-<n>.txt where <n> counts up from 1, so they must be
sorted numerically: a plain lexicographic sort would order report-10.txt
before report-2.txt.
"""

from pathlib import Path

REPORTS_DIR = Path(__file__).resolve().parent / "reports"


def report_order(filename: str) -> tuple[int, str]:
    """Key that puts report-<n>.txt files in numeric order.

    Files whose names do not match report-<n>.txt sort after all numeric ones,
    keeping a deterministic tie-break on the full name.
    """
    stem = filename[:-4] if filename.endswith(".txt") else filename
    if stem.startswith("report-"):
        try:
            return (0, int(stem[len("report-") :]))
        except ValueError:
            pass
    return (1, filename)


