    if not REPORTS_DIR.is_dir():
        raise SystemExit(f"reports directory not found: {REPORTS_DIR}")
    for name in sorted(p.name for p in REPORTS_DIR.iterdir() if p.is_file()):
        pass  # placeholder, replaced below


