#!/usr/bin/env python3
"""Rotate entries in app.log older than 7 days before AS_OF into archive.log."""

import sys
from datetime import datetime, timedelta, timezone

def parse_ts(line: str) -> datetime | None:
    """Extract the leading YYYY-MM-DD HH:MM:SS timestamp from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff = as_of - 7 * 86400  # 7 days in seconds
    cutoff_dt = datetime.fromtimestamp(cutoff, tz=timezone.utc)

    log_path = "app.log"
    archive_path = "archive.log"

    try:
        with open(log_path) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{log_path} not found, nothing to do.", file=sys.stderr)
        return

    keep = []
    archive = []

    for line in lines:
        dt = parse_ts(line)
        if dt is not None and dt < cutoff_dt:
            archive.append(line)
        else:
            keep.append(line)

    # Append expired entries to archive.log
    if archive:
        with open(archive_path, "a") as f:
            f.writelines(archive)

    # Rewrite app.log with remaining entries
    with open(log_path, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

